function capsuleDistance(p,a,b,r) {
  const abx=b.x-a.x, aby=b.y-a.y, apx=p.x-a.x, apy=p.y-a.y;
  const len2=abx*abx+aby*aby;
  const t=len2===0?0:Math.max(0,Math.min(1,(apx*abx+apy*aby)/len2));
  const qx=a.x+t*abx, qy=a.y+t*aby;
  return Math.hypot(p.x-qx,p.y-qy)-r;
}
